required = ['received', 'ram_checked', 'stored', 'status_checked', 'booted']
target = 'example-new'
proof = []

def accept(event, identity=None):
    assert event == required[len(proof)], 'missing earlier evidence'
    if event == 'booted':
        assert identity == target, 'old runtime is still running'
    proof.append(event)
    print(f'{len(proof)}/5 {event}')

for event in required[:-1]:
    accept(event)
try:
    accept('booted', 'example-old')
except AssertionError:
    print('old identity: rejected')
accept('booted', target)
